{
  "verses": [
    {
      "chapter": 22,
      "verse": 4,
      "text_ar": "وأما شجرتي فأخرجت أزهاراً. وثُبِّت عرش الله حيث كانت شجرة الحياة."
    },
    {
      "chapter": 23,
      "verse": 1,
      "text_ar": "ودعا الله آدم قائلاً: «آدم، أين أنت؟ أيمكن أن يخفي البيت عن حضرة"
    },
    {
      "chapter": 23,
      "verse": 2,
      "text_ar": "بانيه؟» فأجاب أبوك: «ليس لأننا نظن أننا لا نُوجَد منك يا رب نتخفى، بل خفتُ لأني عريان، واستحييتُ أمام جبروتك،"
    },
    {
      "chapter": 23,
      "verse": 3,
      "text_ar": "يا سيدي». فقال له الله: «من أراها لك أنك عريان، إلا إن كنت قد تركتَ"
    },
    {
      "chapter": 23,
      "verse": 4,
      "text_ar": "وصيتي التي سلمتها إليك لتحفظها؟» فحينئذ تذكر آدم الكلمة التي كلمته بها (قائلاً): «سأجعلك آمناً أمام الله»؛ فالتفت وقال لي: «لماذا فعلتَ هذا؟» فقلت: «الحية خدعتني»."
    }
  ],
  "book_code": "APMO"
}
